const materials=new Map();const mat=(color,roughness=1)=>{const key=color+':'+roughness;if(!materials.has(key))materials.set(key,new T.MeshStandardMaterial({color,roughness}));return materials.get(key);};
const surfaceOverrides=new Map(),palette={HomeReed:0xb68b45,HomePlaster:0xe6d6ac,HomeWood:0x74513c,Reed:0xc1a15e};
// Shared procedural soil detail, confined to garden beds. No source GLB changes.
// A subdued height map supplies shallow light response, not collision or geometry.
const soilCanvas=document.createElement('canvas');soilCanvas.width=128;soilCanvas.height=128;
const soilContext=soilCanvas.getContext('2d'),soilPixels=soilContext.createImageData(128,128);
for(let y=0;y<128;y++)for(let x=0;x<128;x++){const grain=Math.sin(x*12.9898+y*78.233)*43758.5453,noise=grain-Math.floor(grain),value=Math.round(178+noise*28+8*Math.sin(y*Math.PI/8)),i=(y*128+x)*4;soilPixels.data[i]=soilPixels.data[i+1]=soilPixels.data[i+2]=value;soilPixels.data[i+3]=255;}
soilContext.putImageData(soilPixels,0,0);const soilTexture=new T.CanvasTexture(soilCanvas);soilTexture.wrapS=soilTexture.wrapT=T.RepeatWrapping;soilTexture.repeat.set(2,2);
