// Presentation-only verge masks: route widths and simulation stay authoritative.
function pathSurface(round=false){const canvas=document.createElement('canvas');canvas.width=128;canvas.height=128;const context=canvas.getContext('2d'),pixels=context.createImageData(128,128);for(let y=0;y<128;y++)for(let x=0;x<128;x++){const u=(x-63.5)/63.5,v=(y-63.5)/63.5,edge=round?Math.hypot(u,v):Math.abs(u),jitter=.015*Math.sin(y*.43+x*.29)+.01*Math.cos(y*.71-x*.33),alpha=Math.max(0,Math.min(1,(1-edge+jitter)/.24)),i=(y*128+x)*4;pixels.data[i]=255;pixels.data[i+1]=255;pixels.data[i+2]=255;pixels.data[i+3]=Math.round(alpha*255);}context.putImageData(pixels,0,0);const texture=new T.CanvasTexture(canvas);return new T.MeshStandardMaterial({color:0xc4b38a,map:texture,roughness:1,transparent:true,depthWrite:false,polygonOffset:true,polygonOffsetFactor:-1,polygonOffsetUnits:-1});}
const pathMat=pathSurface(),pathCapMat=pathSurface(true);
const shadowCanvas=document.createElement('canvas');shadowCanvas.width=64;shadowCanvas.height=64;const ctx=shadowCanvas.getContext('2d'),gradient=ctx.createRadialGradient(32,32,3,32,32,31);gradient.addColorStop(0,'rgba(38,48,24,.23)');gradient.addColorStop(1,'rgba(38,48,24,0)');ctx.fillStyle=gradient;ctx.fillRect(0,0,64,64);const shadowMat=new T.MeshBasicMaterial({map:new T.CanvasTexture(shadowCanvas),transparent:true,depthWrite:false});
let revision=0,busy=false;const changed=()=>{revision++;window.RanchView?.changed();};
let plan,state,world,actor,basket,cropGroups={},speed=1,serial=0,following=false;const plotMeshes=[];
async function instance(id,scale){const gltf=await cache.get(id),m=gltf.scene.clone(true),box=new T.Box3().setFromObject(m),c=box.getCenter(new T.Vector3());m.position.set(-c.x,-box.min.y,-c.z);const root=new T.Group();root.add(m);root.scale.setScalar(scale);m.traverse(o=>{if(o.isMesh){o.castShadow=true;o.receiveShadow=true;const recolor=m=>{if(!(m.name in palette))return m;if(!surfaceOverrides.has(m.uuid)){const n=m.clone();n.color.setHex(palette[m.name]);surfaceOverrides.set(m.uuid,n);}return surfaceOverrides.get(m.uuid);};o.material=Array.isArray(o.material)?o.material.map(recolor):recolor(o.material);}});return root;}
function disposeWorld(group){group?.traverse(o=>{if(o.userData.localGeometry)o.geometry?.dispose();if(o.userData.localMaterial)o.material?.dispose();});group?.removeFromParent();}
function mesh(g,m,parent=world){const o=new T.Mesh(g,m);o.userData.localGeometry=true;o.receiveShadow=true;parent.add(o);return o;}
