async function build(){busy=true;const ticket=++serial;$('error').textContent='';$('replant').disabled=true;try{const next=composeV2(catalog,{seed:Number($('seed').value),abundance:$('abundance').value});disposeWorld(world);world=new T.Group();scene.add(world);plan=next;state=createSimulation(plan);cropGroups={};plotMeshes.length=0;
 const data=landscapeMesh(plan),geo=new T.BufferGeometry();geo.setAttribute('position',new T.Float32BufferAttribute(data.positions,3));geo.setIndex(data.indices);geo.computeVertexNormals();const colors=[];for(let i=0;i<data.positions.length;i+=3){const x=data.positions[i],z=data.positions[i+2],v=.5+.18*Math.sin(x*.09+Math.sin(z*.07))*Math.cos(z*.08)+.05*Math.sin(x*.31+z*.23),c=new T.Color().lerpColors(new T.Color('#8ea66d'),new T.Color('#a5b57a'),v);colors.push(c.r,c.g,c.b);}geo.setAttribute('color',new T.Float32BufferAttribute(colors,3));const terrain=mesh(geo,new T.MeshStandardMaterial({vertexColors:true,roughness:1}));terrain.userData.localMaterial=true;
 for(const r of plan.routes){const dx=r.b.x-r.a.x,dz=r.b.z-r.a.z,len=Math.hypot(dx,dz);const p=mesh(new T.PlaneGeometry(r.width+1.1,len),pathMat);p.rotation.set(-Math.PI/2,0,Math.atan2(dx,dz));p.position.set((r.a.x+r.b.x)/2,.035,(r.a.z+r.b.z)/2);for(const v of [r.a,r.b]){const cap=mesh(new T.PlaneGeometry(r.width+1.1,r.width+1.1),pathCapMat);cap.rotation.x=-Math.PI/2;cap.position.set(v.x,.036,v.z);}}
 for(const f of plan.plots){const bed=mesh(new T.BoxGeometry(f.w,.13,f.d),earthMat);bed.position.set(f.x,.055,f.z);bed.userData.plotId=f.id;plotMeshes.push(bed);for(let k=0;k<4;k++){const furrow=mesh(new T.BoxGeometry(f.w-.6,.04,.10),mat(0x9a7c51));furrow.position.set(f.x,.145,f.z-f.d/2+.8+k*(f.d-1.6)/3);}}
 for(const p of plan.placements){const m=await instance(p.assetId,p.scale);if(ticket!==serial)return;m.position.set(p.position.x,p.position.y,p.position.z);m.rotation.y=p.yaw;m.userData.placement=p;world.add(m);
 if(p.group==='orchard'){const top=catalog.assets[p.assetId].dimensionsMetres[2]*p.scale;for(let k=0;k<5;k++){const a=k*2.4,crown=mesh(new T.IcosahedronGeometry(p.radius*.58,1),mat([0x71934c,0x86a35a,0x5f8547][k%3]));crown.position.set(p.position.x+Math.cos(a)*p.radius*.33,top*.7+(k%2)*.8,p.position.z+Math.sin(a)*p.radius*.33);crown.scale.y=.85;crown.castShadow=true;}}
 if(plan.plots.some(f=>f.id===p.group)){(cropGroups[p.group]??=[]).push(m);m.traverse(o=>{if(o.isMesh){o.userData.plotId=p.group;plotMeshes.push(o);}});}const shadow=mesh(new T.PlaneGeometry(p.radius*2.5,p.radius*2.5),shadowMat);shadow.rotation.x=-Math.PI/2;shadow.position.set(p.position.x,.018,p.position.z);}
 actor=await instance(plan.worker.assetId,plan.worker.scale);world.add(actor);basket=await instance('GF-025',.65);basket.position.set(0,.65,.52);actor.add(basket);basket.visible=false;recenter();updateUI();window.v2Evidence={ready:true,plan};
 }catch(e){$('error').textContent=e.message;window.v2Evidence={ready:false,error:e.message};}finally{busy=false;$('replant').disabled=false;changed();}}
function updateUI(){if(!state)return;$('stock').textContent=state.stock;$('deliveries').textContent=state.deliveries+(state.deliveries===1?' delivery':' deliveries');for(const b of document.querySelectorAll('[data-plot]')){const p=state.plots[b.dataset.plot];b.disabled=!p.ready||p.queued;b.querySelector('small').textContent=p.queued?'Queued':p.ready?'Harvest':'Growing '+Math.ceil(p.regrow)+'s';}const w=state.worker;$('activity').textContent=speed===0?'Paused · take a look around':w.phase==='idle'?'Your gardener is ready. Choose a garden.':w.phase==='outbound'?'Off to the '+w.target+' garden':w.phase==='harvesting'?'Gathering a generous harvest…':'Bringing '+w.carrying+' bundles to the storehouse';}
