for(const b of document.querySelectorAll('[data-speed]'))b.onclick=()=>{setSpeed(Number(b.dataset.speed));};
$('replant').onclick=build;$('frame').onclick=()=>{recenter();changed();};$('follow').onclick=()=>follow(!following);$('export').onclick=()=>{if(!plan)return;const u=URL.createObjectURL(new Blob([JSON.stringify({...plan,build:buildInfo,dependencies:Object.fromEntries(Object.entries(catalog.assets).map(([id,a])=>[id,a.sha256]))},null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=u;a.download='little-abundance-v2.json';a.click();setTimeout(()=>URL.revokeObjectURL(u),1000);};
let down=null;renderer.domElement.addEventListener('pointerdown',e=>down={x:e.clientX,y:e.clientY});renderer.domElement.addEventListener('pointerup',e=>{if(!down||Math.hypot(e.clientX-down.x,e.clientY-down.y)>6)return;const r=renderer.domElement.getBoundingClientRect(),ray=new T.Raycaster();ray.setFromCamera(new T.Vector2((e.clientX-r.left)/r.width*2-1,-(e.clientY-r.top)/r.height*2+1),camera);const hit=ray.intersectObjects(plotMeshes,false)[0];if(hit)harvest(hit.object.userData.plotId);});
new ResizeObserver(()=>{const w=stage.clientWidth,h=stage.clientHeight,aspect=w/h,half=aspect<1?37/aspect:37;camera.left=-half*aspect;camera.right=half*aspect;camera.top=half;camera.bottom=-half;camera.updateProjectionMatrix();renderer.setSize(w,h);}).observe(stage);
